'use strict';

// A preamble whose `void` operand has an effect. Node evaluates the operand
// even though its value is discarded, and the export takes its value at the
// real assignments; eliding the write must not elide the operand.
var calls = 0;
function mark() {
  calls++;
}

exports.later = void mark();
exports.later = function () {
  return calls;
};

if (typeof performance === 'object') {
  (function () {
    exports.now = void mark();
    if (typeof performance.now === 'function') {
      exports.now = function () {
        return calls;
      };
    } else {
      exports.now = function () {
        return -1;
      };
    }
  })();
}

exports.calls = function () {
  return calls;
};
